import{_ as o,C as s,o as e,c as n,a3 as t,b as d,w as r,a as l,E as c,a4 as g}from"./chunks/framework.DACwFHq9.js";const v=JSON.parse('{"title":"Diagrams","description":"Create flowcharts and visual diagrams in Notely using Mermaid syntax or the Excalidraw visual canvas.","frontmatter":{"title":"Diagrams","description":"Create flowcharts and visual diagrams in Notely using Mermaid syntax or the Excalidraw visual canvas.","keywords":"mermaid, excalidraw, diagrams, flowchart, sequence diagram, gantt, whiteboard, visual editor","category":"Editor"},"headers":[],"relativePath":"editor/diagrams.md","filePath":"editor/diagrams.md","lastUpdated":1791393216000}'),m={name:"editor/diagrams.md"};function h(p,a,u,b,w,k){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="diagrams" tabindex="-1">Diagrams <a class="header-anchor" href="#diagrams" aria-label="Permalink to &quot;Diagrams&quot;">​</a></h1><p>Notely supports four diagram and visual prototyping formats: <strong>Mermaid</strong> for text-based diagrams written in code, <strong>Excalidraw</strong> for freehand whiteboard-style drawing, <strong>Draw.io</strong> for structured technical schemas and system architectures, and <strong>Wireframe Studio</strong> for responsive low- and high-fidelity UI mockup prototyping.</p><h2 id="mermaid-diagrams" tabindex="-1">Mermaid Diagrams <a class="header-anchor" href="#mermaid-diagrams" aria-label="Permalink to &quot;Mermaid Diagrams&quot;">​</a></h2><p><a href="https://mermaid.js.org/" target="_blank" rel="noreferrer">Mermaid</a> lets you create diagrams using a simple text syntax. Notely renders them live in Preview and Split modes.</p><h3 id="insert-a-mermaid-block" tabindex="-1">Insert a Mermaid Block <a class="header-anchor" href="#insert-a-mermaid-block" aria-label="Permalink to &quot;Insert a Mermaid Block&quot;">​</a></h3><ol><li>In Edit mode, click <strong>Diagram → Mermaid</strong> in the toolbar.</li><li>A Mermaid code block is inserted at the cursor.</li><li>Write your Mermaid syntax inside the block.</li><li>Switch to Split or Preview to see the rendered diagram.</li></ol><h3 id="diagram-types" tabindex="-1">Diagram Types <a class="header-anchor" href="#diagram-types" aria-label="Permalink to &quot;Diagram Types&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```mermaid</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[Open workspace] --&gt; B[Create note]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C{Write content}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[Save note]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[Commit to Git]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><table tabindex="0"><thead><tr><th>Type</th><th>Keyword</th><th>Use for</th></tr></thead><tbody><tr><td>Flowchart</td><td><code>graph TD</code> / <code>graph LR</code></td><td>Processes, decisions, flows</td></tr><tr><td>Sequence</td><td><code>sequenceDiagram</code></td><td>API calls, user interactions</td></tr><tr><td>Gantt</td><td><code>gantt</code></td><td>Project timelines</td></tr><tr><td>Class</td><td><code>classDiagram</code></td><td>Object relationships</td></tr><tr><td>State</td><td><code>stateDiagram-v2</code></td><td>State machines</td></tr><tr><td>ER</td><td><code>erDiagram</code></td><td>Database schemas</td></tr><tr><td>Pie</td><td><code>pie</code></td><td>Data proportions</td></tr></tbody></table><h3 id="example-—-git-workflow" tabindex="-1">Example — Git Workflow <a class="header-anchor" href="#example-—-git-workflow" aria-label="Permalink to &quot;Example — Git Workflow&quot;">​</a></h3>',10)),(e(),d(g,null,{default:r(()=>[c(i,{id:"mermaid-138",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BEdit%20note%5D%20--%3E%20B%5BStage%20changes%5D%0A%20%20%20%20B%20--%3E%20C%5BWrite%20commit%20message%5D%0A%20%20%20%20C%20--%3E%20D%5BCommit%5D%0A%20%20%20%20D%20--%3E%20E%7BPush%20to%20remote%3F%7D%0A%20%20%20%20E%20--%20Yes%20--%3E%20F%5Bgit%20push%5D%0A%20%20%20%20E%20--%20No%20--%3E%20G%5BStay%20local%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="interactive-diagram-actions" tabindex="-1">Interactive Diagram Actions <a class="header-anchor" href="#interactive-diagram-actions" aria-label="Permalink to &quot;Interactive Diagram Actions&quot;">​</a></h3><p>In Preview and Split modes, hovering over any rendered Mermaid diagram reveals the top action bar:</p><ul><li><strong>Edit</strong>: Opens the Mermaid visual editor modal to modify diagram elements visually.</li><li><strong>Download</strong>: Renders and exports the Mermaid diagram as a high-resolution PNG image saved directly to your system Downloads folder.</li></ul><h3 id="troubleshooting-mermaid" tabindex="-1">Troubleshooting Mermaid <a class="header-anchor" href="#troubleshooting-mermaid" aria-label="Permalink to &quot;Troubleshooting Mermaid&quot;">​</a></h3><p>If your diagram does not render:</p><ol><li>Switch to Split mode to see both the source and the error message.</li><li>Check for syntax errors — Mermaid is strict about arrow direction (<code>--&gt;</code> not <code>→</code>).</li><li>Validate with the <a href="https://mermaid.live/" target="_blank" rel="noreferrer">Mermaid Live Editor</a>.</li></ol><hr><h2 id="excalidraw-diagrams" tabindex="-1">Excalidraw Diagrams <a class="header-anchor" href="#excalidraw-diagrams" aria-label="Permalink to &quot;Excalidraw Diagrams&quot;">​</a></h2><p><a href="https://excalidraw.com/" target="_blank" rel="noreferrer">Excalidraw</a> provides a whiteboard canvas for freehand drawing, annotated shapes, and visual diagrams embedded directly in your notes.</p><h3 id="insert-an-excalidraw-diagram" tabindex="-1">Insert an Excalidraw Diagram <a class="header-anchor" href="#insert-an-excalidraw-diagram" aria-label="Permalink to &quot;Insert an Excalidraw Diagram&quot;">​</a></h3><ol><li>Click <strong>Diagram → Excalidraw</strong> in the toolbar.</li><li>An Excalidraw block is inserted in the note.</li><li>In Preview mode, the Excalidraw canvas opens.</li><li>Draw your diagram, then click <strong>Save</strong> to embed it.</li><li>The diagram is stored as a file in your workspace.</li></ol><h3 id="re-edit-an-existing-diagram" tabindex="-1">Re-Edit an Existing Diagram <a class="header-anchor" href="#re-edit-an-existing-diagram" aria-label="Permalink to &quot;Re-Edit an Existing Diagram&quot;">​</a></h3><ol><li>In Preview mode, click the <strong>Edit</strong> button on the Excalidraw preview.</li><li>The canvas reopens with your existing drawing.</li><li>Make changes, then click <strong>Save</strong>.</li></ol><h3 id="convert-an-image-to-excalidraw" tabindex="-1">Convert an Image to Excalidraw <a class="header-anchor" href="#convert-an-image-to-excalidraw" aria-label="Permalink to &quot;Convert an Image to Excalidraw&quot;">​</a></h3><p>You can convert any workspace image into an Excalidraw diagram so you can annotate or draw on top of it:</p><ol><li>In Preview mode, right-click on any workspace image.</li><li>Select <strong>Edit with Excalidraw</strong>.</li><li>The image is placed on the Excalidraw canvas as a resizable background element.</li><li>Draw annotations, arrows, or labels on top.</li><li>Click <strong>Save</strong> to replace the image reference with the Excalidraw diagram.</li></ol><h3 id="restore-the-original-image" tabindex="-1">Restore the Original Image <a class="header-anchor" href="#restore-the-original-image" aria-label="Permalink to &quot;Restore the Original Image&quot;">​</a></h3><p>If you converted an image to Excalidraw and want to revert to the original:</p><ol><li>In Preview mode, right-click the Excalidraw preview.</li><li>Select <strong>Restore original image</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">Restore Availability</p><p>The <strong>Restore original image</strong> option only appears for Excalidraw diagrams that were created from an image conversion. Diagrams created from scratch do not show this option.</p></div><hr><h2 id="draw-io-diagrams" tabindex="-1">Draw.io Diagrams <a class="header-anchor" href="#draw-io-diagrams" aria-label="Permalink to &quot;Draw.io Diagrams&quot;">​</a></h2><p><a href="https://embed.diagrams.net/" target="_blank" rel="noreferrer">Draw.io</a> (diagrams.net) is integrated into Notely for precise, professional engineering schematics, UML designs, and network/cloud architectures.</p><h3 id="insert-a-draw-io-diagram" tabindex="-1">Insert a Draw.io Diagram <a class="header-anchor" href="#insert-a-draw-io-diagram" aria-label="Permalink to &quot;Insert a Draw.io Diagram&quot;">​</a></h3><ol><li>Click the <strong>Insert Diagram</strong> icon (<code>⚡</code>) on the toolbar.</li><li>Click <strong>Draw.io</strong>.</li><li>In Preview mode, click on the placeholder to open the Draw.io editor.</li><li>Build your diagram and click <strong>Save Diagram</strong>.</li><li>The diagram saves XML source metadata to <code>media/draw.io/*.drawio</code> and renders a preview image to <code>media/draw.io/*.png</code>.</li></ol><h3 id="import-diagrams-via-drag-and-drop" tabindex="-1">Import Diagrams via Drag and Drop <a class="header-anchor" href="#import-diagrams-via-drag-and-drop" aria-label="Permalink to &quot;Import Diagrams via Drag and Drop&quot;">​</a></h3><p>Drop any existing <code>.drawio</code> or <code>.drawio.xml</code> file directly into the Markdown Editor. Notely will parse the file, copy it into the workspace media directory, and embed it as an interactive diagram block.</p><hr><h2 id="wireframe-studio" tabindex="-1">Wireframe Studio <a class="header-anchor" href="#wireframe-studio" aria-label="Permalink to &quot;Wireframe Studio&quot;">​</a></h2><p><strong>Wireframe Studio</strong> is Notely&#39;s integrated, visual UI prototyping tool powered by GrapesJS. It provides a drag-and-drop studio designed for rapid wireframing of desktop, tablet, and mobile user interfaces directly within your notes.</p><h3 id="insert-a-wireframe" tabindex="-1">Insert a Wireframe <a class="header-anchor" href="#insert-a-wireframe" aria-label="Permalink to &quot;Insert a Wireframe&quot;">​</a></h3><ol><li>Click the <strong>Insert Diagram</strong> icon (<code>⚡</code>) on the Markdown toolbar.</li><li>Select <strong>Wireframe</strong>.</li><li>A wireframe placeholder markdown tag is inserted:<div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Wireframe Diagram</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">media/wireframes/&lt;diagram-id&gt;.png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">){data-diagram-id=&quot;&lt;diagram-id&gt;&quot;}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li>In Preview mode, click the placeholder to open <strong>Wireframe Studio</strong>.</li></ol><h3 id="stencil-library-components" tabindex="-1">Stencil Library &amp; Components <a class="header-anchor" href="#stencil-library-components" aria-label="Permalink to &quot;Stencil Library &amp; Components&quot;">​</a></h3><p>The left sidebar organizes over 100 UI stencils into searchable categories:</p><ul><li><strong>Layouts</strong>: Grid layouts, 2-column/3-column splits, cards, split-screens, and dashboard shells.</li><li><strong>Forms &amp; Inputs</strong>: Text inputs, checkboxes, toggle switches, select dropdowns, search bars, and date pickers.</li><li><strong>UI Elements</strong>: Buttons, badges, breadcrumbs, tabs, avatars, pagination, tooltips, and progress bars.</li><li><strong>Headers &amp; Navigation</strong>: Top navigation bars, sidebars, sub-headers, and mobile app bars.</li><li><strong>Hero &amp; Content Sections</strong>: Hero banners, feature grids, CTA blocks, and pricing cards.</li><li><strong>Metrics &amp; Feedback</strong>: Metric stat cards, alert banners, toast notifications, modals, and empty state cards.</li><li><strong>Tables &amp; Lists</strong>: Data tables, striped tables, and interactive list groups.</li><li><strong>Device Frames</strong>: Browser windows, mobile phone bezels, and tablet mockups.</li><li><strong>FontAwesome Icons</strong>: Standard icon library elements for UI actions and navigation.</li></ul><h3 id="viewport-controls-canvas-tools" tabindex="-1">Viewport Controls &amp; Canvas Tools <a class="header-anchor" href="#viewport-controls-canvas-tools" aria-label="Permalink to &quot;Viewport Controls &amp; Canvas Tools&quot;">​</a></h3><ul><li><strong>Responsive Viewports</strong>: Switch instantly between <strong>Desktop (100%)</strong>, <strong>Tablet (768px)</strong>, and <strong>Mobile (375px)</strong> to verify responsive layouts.</li><li><strong>Zoom &amp; Pan</strong>: Zoom in/out or fit to screen using bottom status bar controls.</li><li><strong>Undo / Redo</strong>: Quick hotkeys (<code>Ctrl/Cmd + Z</code> / <code>Ctrl/Cmd + Y</code>) and toolbar actions.</li><li><strong>Component Outlines &amp; Guides</strong>: Toggle visual wireframe guides to inspect bounding boxes and alignment.</li></ul><h3 id="inspector-properties-structure-annotations" tabindex="-1">Inspector: Properties, Structure &amp; Annotations <a class="header-anchor" href="#inspector-properties-structure-annotations" aria-label="Permalink to &quot;Inspector: Properties, Structure &amp; Annotations&quot;">​</a></h3><p>The right Inspector panel offers three dedicated modes:</p><ol><li><strong>Properties</strong>: Adjust typography, sizing, spacing, borders, background colors, and component attributes.</li><li><strong>Structure</strong>: Visual DOM layer tree for inspecting parent-child component hierarchies and reordering elements.</li><li><strong>Annotations</strong>: Add design notes, rationale, and UX specifications tied directly to selected wireframe blocks.</li></ol><h3 id="saving-storage" tabindex="-1">Saving &amp; Storage <a class="header-anchor" href="#saving-storage" aria-label="Permalink to &quot;Saving &amp; Storage&quot;">​</a></h3><ul><li>Clicking <strong>Save Wireframe</strong> renders a PNG preview to <code>media/wireframes/&lt;id&gt;.png</code> and persists the full project structure to <code>.notes-app/wireframes/&lt;id&gt;.wireframe.json</code>.</li><li>Wireframes are fully offline, Git-trackable, and cataloged in the <strong>Diagrams &amp; Media Gallery</strong> (<code>Ctrl/Cmd + Alt + M</code>) under the <strong>UI Prototypes</strong> category.</li></ul><hr><h2 id="choosing-a-diagram-tool" tabindex="-1">Choosing a Diagram Tool <a class="header-anchor" href="#choosing-a-diagram-tool" aria-label="Permalink to &quot;Choosing a Diagram Tool&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Mermaid</th><th>Excalidraw</th><th>Draw.io</th><th>Wireframe Studio</th></tr></thead><tbody><tr><td><strong>Best for</strong></td><td>Fast text-based flows, timelines</td><td>Casual sketching, whiteboard</td><td>Engineering schematics, network charts</td><td>UI prototyping, app mockups, layout wireframes</td></tr><tr><td><strong>Editing</strong></td><td>Text syntax</td><td>Visual canvas</td><td>Visual canvas</td><td>Drag-and-drop component studio</td></tr><tr><td><strong>Storage</strong></td><td>Plain Markdown text</td><td>JSON <code>.excalidraw</code> + SVG</td><td>XML <code>.drawio</code> + PNG</td><td>JSON <code>.wireframe.json</code> + PNG</td></tr><tr><td><strong>Offline</strong></td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr></tbody></table>',45))])}const E=o(m,[["render",h]]);export{v as __pageData,E as default};
